/* =============================================================================
   OneShop - large development seed - 04_reviews.sql
   Reviews (only customers with a COMPLETED order containing the product), then identity reseed
   GENERATED by src/test/java/com/oneshop/seed/LargeSeedGenerator.java - do not edit by hand.
   Dev data only (all IDs >= 1000; 04_seed_data.sql rows are kept). See docs/SEED_LARGE.md.
   ========================================================================== */
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
GO
DECLARE @now DATETIME2(0) = SYSDATETIME();

BEGIN TRANSACTION;
SET IDENTITY_INSERT dbo.reviews ON;
SET IDENTITY_INSERT dbo.reviews OFF;

COMMIT TRANSACTION;
GO
/* identity reseed: new rows created by the application never collide with seed ids */
DECLARE @m_users BIGINT = (SELECT ISNULL(MAX(user_id), 0) FROM dbo.users);
DBCC CHECKIDENT ('dbo.users', RESEED, @m_users) WITH NO_INFOMSGS;
DECLARE @m_customer_addresses BIGINT = (SELECT ISNULL(MAX(address_id), 0) FROM dbo.customer_addresses);
DBCC CHECKIDENT ('dbo.customer_addresses', RESEED, @m_customer_addresses) WITH NO_INFOMSGS;
DECLARE @m_stores BIGINT = (SELECT ISNULL(MAX(store_id), 0) FROM dbo.stores);
DBCC CHECKIDENT ('dbo.stores', RESEED, @m_stores) WITH NO_INFOMSGS;
DECLARE @m_staff_store_assignments BIGINT = (SELECT ISNULL(MAX(assignment_id), 0) FROM dbo.staff_store_assignments);
DBCC CHECKIDENT ('dbo.staff_store_assignments', RESEED, @m_staff_store_assignments) WITH NO_INFOMSGS;
DECLARE @m_categories BIGINT = (SELECT ISNULL(MAX(category_id), 0) FROM dbo.categories);
DBCC CHECKIDENT ('dbo.categories', RESEED, @m_categories) WITH NO_INFOMSGS;
DECLARE @m_brands BIGINT = (SELECT ISNULL(MAX(brand_id), 0) FROM dbo.brands);
DBCC CHECKIDENT ('dbo.brands', RESEED, @m_brands) WITH NO_INFOMSGS;
DECLARE @m_products BIGINT = (SELECT ISNULL(MAX(product_id), 0) FROM dbo.products);
DBCC CHECKIDENT ('dbo.products', RESEED, @m_products) WITH NO_INFOMSGS;
DECLARE @m_product_images BIGINT = (SELECT ISNULL(MAX(image_id), 0) FROM dbo.product_images);
DBCC CHECKIDENT ('dbo.product_images', RESEED, @m_product_images) WITH NO_INFOMSGS;
DECLARE @m_store_products BIGINT = (SELECT ISNULL(MAX(store_product_id), 0) FROM dbo.store_products);
DBCC CHECKIDENT ('dbo.store_products', RESEED, @m_store_products) WITH NO_INFOMSGS;
DECLARE @m_carts BIGINT = (SELECT ISNULL(MAX(cart_id), 0) FROM dbo.carts);
DBCC CHECKIDENT ('dbo.carts', RESEED, @m_carts) WITH NO_INFOMSGS;
DECLARE @m_cart_items BIGINT = (SELECT ISNULL(MAX(cart_item_id), 0) FROM dbo.cart_items);
DBCC CHECKIDENT ('dbo.cart_items', RESEED, @m_cart_items) WITH NO_INFOMSGS;
DECLARE @m_checkout_sessions BIGINT = (SELECT ISNULL(MAX(checkout_id), 0) FROM dbo.checkout_sessions);
DBCC CHECKIDENT ('dbo.checkout_sessions', RESEED, @m_checkout_sessions) WITH NO_INFOMSGS;
DECLARE @m_orders BIGINT = (SELECT ISNULL(MAX(order_id), 0) FROM dbo.orders);
DBCC CHECKIDENT ('dbo.orders', RESEED, @m_orders) WITH NO_INFOMSGS;
DECLARE @m_order_items BIGINT = (SELECT ISNULL(MAX(order_item_id), 0) FROM dbo.order_items);
DBCC CHECKIDENT ('dbo.order_items', RESEED, @m_order_items) WITH NO_INFOMSGS;
DECLARE @m_payments BIGINT = (SELECT ISNULL(MAX(payment_id), 0) FROM dbo.payments);
DBCC CHECKIDENT ('dbo.payments', RESEED, @m_payments) WITH NO_INFOMSGS;
DECLARE @m_inventory_movements BIGINT = (SELECT ISNULL(MAX(movement_id), 0) FROM dbo.inventory_movements);
DBCC CHECKIDENT ('dbo.inventory_movements', RESEED, @m_inventory_movements) WITH NO_INFOMSGS;
DECLARE @m_order_status_history BIGINT = (SELECT ISNULL(MAX(history_id), 0) FROM dbo.order_status_history);
DBCC CHECKIDENT ('dbo.order_status_history', RESEED, @m_order_status_history) WITH NO_INFOMSGS;
DECLARE @m_reviews BIGINT = (SELECT ISNULL(MAX(review_id), 0) FROM dbo.reviews);
